export function getServiceInformationKey() {
  return ['service_information'] as const
}

export function getV2_1Key() {
  return ['v2.1'] as const
}

export function getServiceInformationQueryKey() {
  return ['service_information', '/service_information'] as const
}

export function getServiceInformationQueryOptions(options?: ClientRequestOptions) {
  return {
    queryKey: getServiceInformationQueryKey(),
    queryFn({ signal }: QueryFunctionContext) {
      return parseResponse(
        client.service_information.$get(undefined, {
          ...options,
          init: { ...options?.init, signal },
        }),
      )
    },
  }
}

